* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;
    background-color: #f5f5f5;
    color: #333;
}

.container {
    max-width: 1600px;
    margin: 0 auto;
    padding: 20px;
    background-color: white;
    min-height: 100vh;
}

h1 {
    text-align: center;
    margin-bottom: 30px;
    color: #2c3e50;
    font-size: 2.5em;
}

h2 {
    margin-bottom: 15px;
    color: #34495e;
    font-size: 1.5em;
}

.content {
    display: flex;
    gap: 30px;
    align-items: flex-start;
}

.chart-section {
    flex: 1;
    min-width: 0;
}

.table-section {
    flex: 1;
    min-width: 0;
    max-height: 90vh;
    overflow-y: auto;
}

#bubble-chart {
    background-color: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 600px;
}

#legend {
    margin-top: 20px;
    padding: 15px;
    background-color: #f9f9f9;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 10px;
}

.legend-item {
    display: flex;
    align-items: center;
    gap: 8px;
    font-size: 0.9em;
}

.legend-color {
    width: 16px;
    height: 16px;
    border-radius: 50%;
    border: 1px solid #999;
}

#table-container {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
}

table {
    width: 100%;
    border-collapse: collapse;
    font-size: 0.9em;
}

thead {
    background-color: #34495e;
    color: white;
    position: sticky;
    top: 0;
    z-index: 10;
}

th {
    padding: 12px;
    text-align: left;
    font-weight: 600;
}

td {
    padding: 10px 12px;
    border-bottom: 1px solid #e0e0e0;
}

tbody tr {
    transition: background-color 0.2s ease;
    cursor: pointer;
}

tbody tr:hover {
    background-color: #ecf0f1;
}

tbody tr.selected {
    background-color: #3498db;
    color: white;
}

tbody tr.selected:hover {
    background-color: #2980b9;
}

.tooltip {
    position: absolute;
    background-color: rgba(0, 0, 0, 0.8);
    color: white;
    padding: 10px 12px;
    border-radius: 6px;
    font-size: 0.85em;
    pointer-events: none;
    z-index: 1000;
    max-width: 250px;
    word-wrap: break-word;
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}

.tooltip.hidden {
    display: none;
}

circle {
    stroke: white;
    stroke-width: 2px;
    transition: filter 0.2s ease;
}

circle:hover {
    filter: brightness(1.1);
    stroke-width: 3px;
}

circle.selected {
    stroke: white;
    stroke-width: 3px;
    filter: brightness(1.15);
}

text.bubble-label {
    font-size: 12px;
    font-weight: bold;
    text-anchor: middle;
    dominant-baseline: middle;
    pointer-events: none;
    user-select: none;
}

@media (max-width: 1200px) {
    .content {
        flex-direction: column;
    }

    #legend {
        grid-template-columns: repeat(3, 1fr);
    }
}

@media (max-width: 768px) {
    .container {
        padding: 10px;
    }

    h1 {
        font-size: 1.8em;
        margin-bottom: 20px;
    }

    h2 {
        font-size: 1.2em;
    }

    .content {
        gap: 15px;
    }

    #legend {
        grid-template-columns: repeat(2, 1fr);
    }

    #bubble-chart {
        min-height: 400px;
    }

    table {
        font-size: 0.8em;
    }

    th, td {
        padding: 8px;
    }
}

