// Load and process data
Promise.all([
    d3.csv('data/stock-descriptions.csv'),
    d3.csv('data/stock-descriptions.csv')
]).then(([stockData]) => {
    // Parse numeric fields
    stockData.forEach(d => {
        d.marketCap = d.marketCap ? parseFloat(d.marketCap) : null;
        d.fullTimeEmployees = d.fullTimeEmployees ? parseFloat(d.fullTimeEmployees) : null;
        d.returnOnEquity = d.returnOnEquity ? parseFloat(d.returnOnEquity) : null;
        d.revenuePerShare = d.revenuePerShare ? parseFloat(d.revenuePerShare) : null;
        d.bookValue = d.bookValue ? parseFloat(d.bookValue) : null;
        d.yield = d.yield ? parseFloat(d.yield) : null;
        d.beta = d.beta ? parseFloat(d.beta) : null;
    });

    // Get unique sectors for coloring
    const sectors = [...new Set(stockData.map(d => d.sector))].sort();

    // Color scale
    const colorScale = d3.scaleOrdinal()
        .domain(sectors)
        .range(d3.schemeCategory10);

    // Initialize bubble chart
    initBubbleChart(stockData, sectors, colorScale);

    // Initialize table
    initTable(stockData, colorScale);
});

function initBubbleChart(data, sectors, colorScale) {
    const margin = { top: 20, right: 20, bottom: 20, left: 20 };
    const width = document.getElementById('bubble-chart').parentElement.offsetWidth - 40;
    const height = Math.max(600, window.innerHeight * 0.75);

    const svg = d3.select('#bubble-chart')
        .html('')
        .append('svg')
        .attr('width', width)
        .attr('height', height)
        .attr('viewBox', [0, 0, width, height])
        .attr('style', 'max-width: 100%; height: auto;');

    const g = svg.append('g')
        .attr('transform', `translate(${margin.left},${margin.top})`);

    const chartWidth = width - margin.left - margin.right;
    const chartHeight = height - margin.top - margin.bottom;

    // Create simulation with forces
    const simulation = d3.forceSimulation(data)
        .force('x', d3.forceX(d => {
            // Position by sector horizontally
            const sectorIndex = sectors.indexOf(d.sector);
            return (sectorIndex + 1) * (chartWidth / (sectors.length + 1));
        }).strength(0.05))
        .force('y', d3.forceY(chartHeight / 2).strength(0.02))
        .force('collide', d3.forceCollide(d => {
            // Size bubble by market cap or uniform for ETFs
            const isETF = d.sector === 'ETF';
            if (isETF) return 35;

            // For stocks with market cap data
            const scaleFactor = Math.pow(Math.abs(d.marketCap || 100000000000), 0.5) / Math.pow(3000000000000, 0.5);
            return Math.max(20, scaleFactor * 50);
        }).strength(1))
        .force('charge', d3.forceManyBody().strength(-100))
        .stop();

    // Run simulation
    for (let i = 0; i < 300; i++) simulation.tick();

    // Create circles for bubbles
    const circles = g.selectAll('circle')
        .data(data)
        .enter()
        .append('circle')
        .attr('cx', d => d.x)
        .attr('cy', d => d.y)
        .attr('r', d => {
            const isETF = d.sector === 'ETF';
            if (isETF) return 35;

            const scaleFactor = Math.pow(Math.abs(d.marketCap || 100000000000), 0.5) / Math.pow(3000000000000, 0.5);
            return Math.max(20, scaleFactor * 50);
        })
        .attr('fill', d => colorScale(d.sector))
        .attr('opacity', 0.8)
        .attr('class', 'bubble')
        .attr('data-ticker', d => d.ticker);

    // Add labels inside bubbles
    const labels = g.selectAll('text.bubble-label')
        .data(data)
        .enter()
        .append('text')
        .attr('class', 'bubble-label')
        .attr('x', d => d.x)
        .attr('y', d => d.y)
        .text(d => d.ticker)
        .attr('fill', 'white')
        .attr('pointer-events', 'none');

    // Tooltip
    const tooltip = d3.select('#tooltip');

    // Add hover and click interactions
    circles.on('mouseover', function(event, d) {
        if (d.sector !== 'ETF' && d.marketCap) {
            const marketCapFormatted = formatMarketCap(d.marketCap);
            tooltip.style('display', 'block')
                .html(`<strong>${d.ticker}</strong><br/>${d['full name']}<br/>${d.sector}<br/>Market Cap: ${marketCapFormatted}`);
        }
    })
    .on('mousemove', function(event) {
        tooltip.style('left', (event.pageX + 10) + 'px')
            .style('top', (event.pageY + 10) + 'px');
    })
    .on('mouseout', function() {
        tooltip.style('display', 'none');
    })
    .on('click', function(event, d) {
        event.stopPropagation();
        clearSelections();

        // Select this bubble
        d3.select(this)
            .classed('selected', true)
            .raise();

        // Select corresponding table row
        d3.selectAll(`tr[data-ticker="${d.ticker}"]`)
            .classed('selected', true);
    });

    // Create legend
    const legendContainer = d3.select('#legend');
    legendContainer.html('');

    sectors.forEach(sector => {
        const item = legendContainer.append('div')
            .attr('class', 'legend-item');

        item.append('div')
            .attr('class', 'legend-color')
            .style('background-color', colorScale(sector));

        item.append('span')
            .text(sector);
    });
}

function initTable(data, colorScale) {
    const tbody = d3.select('#table-body');

    const rows = tbody.selectAll('tr')
        .data(data)
        .enter()
        .append('tr')
        .attr('data-ticker', d => d.ticker);

    // Add cells to each row
    rows.append('td').text(d => d.ticker);
    rows.append('td').text(d => d['full name']);
    rows.append('td').text(d => d.sector);
    rows.append('td').text(d => {
        if (d.marketCap) {
            return formatMarketCap(d.marketCap);
        }
        return 'N/A';
    });

    // Add click interactions to rows
    rows.on('click', function(event, d) {
        event.stopPropagation();
        clearSelections();

        // Select this row
        d3.select(this)
            .classed('selected', true);

        // Select corresponding bubble
        d3.selectAll(`circle[data-ticker="${d.ticker}"]`)
            .classed('selected', true)
            .raise();

        // Scroll to center the row
        this.scrollIntoView({ behavior: 'smooth', block: 'center' });
    });

    // Clear selection when clicking elsewhere
    document.addEventListener('click', function(event) {
        if (!event.target.closest('circle') && !event.target.closest('tr')) {
            clearSelections();
        }
    });
}

function clearSelections() {
    d3.selectAll('circle.selected').classed('selected', false);
    d3.selectAll('tr.selected').classed('selected', false);
}

function formatMarketCap(value) {
    if (!value) return 'N/A';

    const absValue = Math.abs(value);

    if (absValue >= 1e12) {
        return (value / 1e12).toFixed(2) + 'T';
    } else if (absValue >= 1e9) {
        return (value / 1e9).toFixed(2) + 'B';
    } else if (absValue >= 1e6) {
        return (value / 1e6).toFixed(2) + 'M';
    }

    return value.toFixed(2);
}

// Handle window resize
window.addEventListener('resize', () => {
    location.reload();
});

